#!/usr/bin/env bash
# K-fold 10-class experiment runner.
#
# Uses folds from dataset/processed/kfold_paper10c_w125/ generated by
# scripts/generate_kfold_splits_10class.py (calfId 1306 always in train,
# calfId 1357 always in test — guarantees Play in both splits every fold).
#
# For each fold × feature set (hc / catch22 / rocket / tsfel):
#   - builds feature parquets (if not already done)
#   - runs the full supervised grid:
#       RF baseline + RF hypersearch + TSFEL-MLP
#       + cnn_lstm / robust / patchtst × deep_only/hybrid × fromscratch/frompretrain
#
# Usage:
#   bash scripts/experiments/run_kfold_paper10c.sh
# Overrides:
#   KFOLD_RUN_DIR=experiments/kfold_paper10c_w125/runs/myrun \
#   N_FOLDS=5 SEED=2026 \
#   bash scripts/experiments/run_kfold_paper10c.sh

set -euo pipefail
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

export WINDOW_LEN=125
export WINDOW_STRIDE=62
export DATASET_ID="AcTBeCalf_paper_w125"

# shellcheck source=_common.sh
source "${DIR}/_common.sh"

N_FOLDS="${N_FOLDS:-5}"
KFOLD_DATA_DIR="${KFOLD_DATA_DIR:-${REPO_ROOT}/dataset/processed/kfold_paper10c_w125}"
TIMESTAMP="$(date +%Y-%m-%d_%H-%M-%S)"
KFOLD_RUN_DIR="${KFOLD_RUN_DIR:-${REPO_ROOT}/experiments/kfold_paper10c_w125/runs/kfold_${TIMESTAMP}}"
LABEL_MAP="${REPO_ROOT}/scripts/label_maps/paper_10class.json"

[ -f "$LABEL_MAP" ] || { echo "ERROR: label map not found: ${LABEL_MAP}" >&2; exit 1; }

# --- Step 0: generate fold splits if not done ---
if [ ! -f "${KFOLD_DATA_DIR}/fold_assignments.json" ]; then
    echo ">>> Generating ${N_FOLDS} 10-class folds → ${KFOLD_DATA_DIR}"
    python "${REPO_ROOT}/scripts/generate_kfold_splits_10class.py" \
        --csv "${REPO_ROOT}/dataset/AcTBeCalf.csv" \
        --out-dir "${KFOLD_DATA_DIR}" \
        --n-folds "${N_FOLDS}"
else
    echo ">>> Fold splits already exist at ${KFOLD_DATA_DIR}, skipping generation"
fi

mkdir -p "${KFOLD_RUN_DIR}"
echo ">>> kfold paper10c run: ${KFOLD_RUN_DIR}"
echo ">>> window=${WINDOW_LEN}  folds=${N_FOLDS}  seed=${SEED}"

# --- Pretrain checkpoints (w125, reused from paper6c) ---
CNN_CKPT="${PRETRAIN_BASE}/ts2vec_pretrain_cnn_lstm_${DATASET_ID}_ep${PRETRAIN_EPOCHS}_s${SEED}/ts2vec_best.pt"
ROB_CKPT="${PRETRAIN_BASE}/ts2vec_pretrain_robust_${DATASET_ID}_ep${PRETRAIN_EPOCHS}_s${SEED}/ts2vec_best.pt"
PATCHTST_CKPT="${PRETRAIN_BASE}/patchtst_pretrain_raw_${DATASET_ID}_ep${PATCHTST_PRETRAIN_EPOCHS}_bs${PATCHTST_PRETRAIN_BATCH_SIZE}_lr${PRETRAIN_LR}_s${SEED}/best.pt"

for ckpt in "$CNN_CKPT" "$ROB_CKPT" "$PATCHTST_CKPT"; do
    [ -f "$ckpt" ] || { echo "ERROR: pretrain checkpoint missing: $ckpt" >&2; exit 1; }
done

echo ">>> cnn ckpt:      ${CNN_CKPT}"
echo ">>> robust ckpt:   ${ROB_CKPT}"
echo ">>> patchtst ckpt: ${PATCHTST_CKPT}"

# --- Per-fold loop ---
for k in $(seq 0 $((N_FOLDS - 1))); do
    FOLD_DATA_DIR="${KFOLD_DATA_DIR}/fold_${k}"

    [ -f "${FOLD_DATA_DIR}/train.parquet" ] || {
        echo "ERROR: ${FOLD_DATA_DIR}/train.parquet missing" >&2; exit 1; }

    echo ""
    echo "========================================================"
    echo ">>> FOLD ${k} / $((N_FOLDS - 1))"
    echo "========================================================"

    for FEAT in hc catch22 rocket tsfel; do
        FEAT_DIR="${FOLD_DATA_DIR}/${FEAT}"
        mkdir -p "$FEAT_DIR"

        echo ""
        echo ">>> fold_${k}/${FEAT}: windowing"

        if [ "$FEAT" = tsfel ]; then
            WIN_TRAIN="${FEAT_DIR}/windowed_tsfel_train.parquet"
            WIN_TEST="${FEAT_DIR}/windowed_tsfel_test.parquet"
            MANIFEST="${FEAT_DIR}/tsfel_feature_manifest.json"

            if [ ! -f "$WIN_TRAIN" ] || [ ! -f "$MANIFEST" ]; then
                python "${REPO_ROOT}/scripts/prepare_windowed_parquet.py" \
                    --input "${FOLD_DATA_DIR}/train.parquet" \
                    --output "$WIN_TRAIN" \
                    --feature-manifest-out "$MANIFEST" \
                    --window-size "$WINDOW_LEN" \
                    --overlap 0.5 \
                    --remap-labels "$LABEL_MAP"
            else
                echo ">>> fold_${k}/tsfel train exists, skipping"
            fi

            if [ ! -f "$WIN_TEST" ]; then
                python "${REPO_ROOT}/scripts/prepare_windowed_parquet.py" \
                    --input "${FOLD_DATA_DIR}/test.parquet" \
                    --output "$WIN_TEST" \
                    --feature-manifest-in "$MANIFEST" \
                    --window-size "$WINDOW_LEN" \
                    --overlap 0.5 \
                    --remap-labels "$LABEL_MAP"
            else
                echo ">>> fold_${k}/tsfel test exists, skipping"
            fi

        else
            WIN_TRAIN="${FEAT_DIR}/windowed_${FEAT}_train.parquet"
            WIN_TEST="${FEAT_DIR}/windowed_${FEAT}_test.parquet"
            ROCKET_MODEL="${FEAT_DIR}/rocket_model.joblib"

            EXTRA_TRAIN=()
            EXTRA_TEST=()
            if [ "$FEAT" = rocket ]; then
                EXTRA_TRAIN+=(--rocket-manifest-out "$ROCKET_MODEL")
                EXTRA_TEST+=( --rocket-manifest-in  "$ROCKET_MODEL")
            fi

            if [ ! -f "$WIN_TRAIN" ]; then
                python "${REPO_ROOT}/scripts/prepare_paper_features_parquet.py" \
                    --features "$FEAT" \
                    --input "${FOLD_DATA_DIR}/train.parquet" \
                    --output "$WIN_TRAIN" \
                    --window-size "$WINDOW_LEN" \
                    --overlap 0.5 \
                    --purity-threshold 0.9 \
                    --remap-labels "$LABEL_MAP" \
                    "${EXTRA_TRAIN[@]}"
            else
                echo ">>> fold_${k}/${FEAT} train exists, skipping"
            fi

            if [ ! -f "$WIN_TEST" ]; then
                python "${REPO_ROOT}/scripts/prepare_paper_features_parquet.py" \
                    --features "$FEAT" \
                    --input "${FOLD_DATA_DIR}/test.parquet" \
                    --output "$WIN_TEST" \
                    --window-size "$WINDOW_LEN" \
                    --overlap 0.5 \
                    --purity-threshold 0.9 \
                    --remap-labels "$LABEL_MAP" \
                    "${EXTRA_TEST[@]}"
            else
                echo ">>> fold_${k}/${FEAT} test exists, skipping"
            fi
        fi

        # --- Supervised experiments for this fold/feature ---
        export TRAIN_PARQUET="$WIN_TRAIN"
        export TEST_PARQUET="$WIN_TEST"
        export DATASET_ID="AcTBeCalf_paper10c_${FEAT}"
        export EXPERIMENTS_BASE="${KFOLD_RUN_DIR}/${FEAT}/fold_${k}"
        mkdir -p "${EXPERIMENTS_BASE}"
        unset FREEZE_ENCODER || true

        echo ">>> fold_${k}/${FEAT}: RF baseline"
        RF_OUT="${EXPERIMENTS_BASE}/rf_baseline_${DATASET_ID}_s${SEED}"
        if [ ! -f "${RF_OUT}/DONE" ]; then
            mkdir -p "$RF_OUT"
            python -m random_forest_baseline.tsfel_baseline \
                --train "$TRAIN_PARQUET" --test "$TEST_PARQUET" \
                --output_dir "$RF_OUT" --seed "$SEED" \
                2>&1 | tee -a "${RF_OUT}/train.log"
            touch "${RF_OUT}/DONE"
        else
            echo ">>> fold_${k}/${FEAT}: RF baseline already done, skipping"
        fi

        echo ">>> fold_${k}/${FEAT}: RF hypersearch (val_fraction=${VAL_FRACTION})"
        RFH_OUT="${EXPERIMENTS_BASE}/rf_hypersearch_${DATASET_ID}_s${SEED}"
        if [ ! -f "${RFH_OUT}/DONE" ]; then
            mkdir -p "$RFH_OUT"
            python -m random_forest_baseline.rf_hypersearch \
                --train "$TRAIN_PARQUET" --test "$TEST_PARQUET" \
                --val_fraction "$VAL_FRACTION" --seed "$SEED" \
                --output_dir "$RFH_OUT" \
                2>&1 | tee -a "${RFH_OUT}/train.log"
            touch "${RFH_OUT}/DONE"
        else
            echo ">>> fold_${k}/${FEAT}: RF hypersearch already done, skipping"
        fi

        echo ">>> fold_${k}/${FEAT}: TSFEL-MLP"
        BATCH_SIZE="$BATCH_SIZE_LARGE" unset RUN_SUFFIX 2>/dev/null || true
        BATCH_SIZE="$BATCH_SIZE_LARGE" run_experiment tsfel_mlp tsfel_only
        BATCH_SIZE="$BATCH_SIZE_LARGE" run_finetune   tsfel_mlp tsfel_only

        for MODE in deep_only hybrid; do
            echo ">>> fold_${k}/${FEAT}: cnn_lstm ${MODE}"
            BATCH_SIZE="$BATCH_SIZE_LARGE" RUN_SUFFIX=fromscratch \
                run_experiment cnn_lstm "$MODE"
            BATCH_SIZE="$BATCH_SIZE_LARGE" RUN_SUFFIX=fromscratch \
                run_finetune   cnn_lstm "$MODE"
            BATCH_SIZE="$BATCH_SIZE_LARGE" RUN_SUFFIX="frompretrain_raw_ep${PRETRAIN_EPOCHS}" \
                run_experiment cnn_lstm "$MODE" --init_encoder_from "$CNN_CKPT"
            BATCH_SIZE="$BATCH_SIZE_LARGE" RUN_SUFFIX="frompretrain_raw_ep${PRETRAIN_EPOCHS}" \
                run_finetune   cnn_lstm "$MODE"

            echo ">>> fold_${k}/${FEAT}: robust ${MODE}"
            BATCH_SIZE="$BATCH_SIZE_LARGE" RUN_SUFFIX=fromscratch \
                run_experiment robust "$MODE"
            BATCH_SIZE="$BATCH_SIZE_LARGE" RUN_SUFFIX=fromscratch \
                run_finetune   robust "$MODE"
            BATCH_SIZE="$BATCH_SIZE_LARGE" RUN_SUFFIX="frompretrain_raw_ep${PRETRAIN_EPOCHS}" \
                run_experiment robust "$MODE" --init_encoder_from "$ROB_CKPT"
            BATCH_SIZE="$BATCH_SIZE_LARGE" RUN_SUFFIX="frompretrain_raw_ep${PRETRAIN_EPOCHS}" \
                run_finetune   robust "$MODE"

            echo ">>> fold_${k}/${FEAT}: patchtst ${MODE}"
            BATCH_SIZE="$PATCHTST_BATCH_SIZE" RUN_SUFFIX=fromscratch \
                run_experiment patchtst "$MODE" --context_length "$WINDOW_LEN"
            BATCH_SIZE="$PATCHTST_BATCH_SIZE" RUN_SUFFIX=fromscratch \
                run_finetune   patchtst "$MODE" --context_length "$WINDOW_LEN"
            BATCH_SIZE="$PATCHTST_BATCH_SIZE" RUN_SUFFIX="frompretrain_raw_ep${PATCHTST_PRETRAIN_EPOCHS}" \
                run_experiment patchtst "$MODE" \
                    --patchtst_checkpoint "$PATCHTST_CKPT" --context_length "$WINDOW_LEN"
            BATCH_SIZE="$PATCHTST_BATCH_SIZE" RUN_SUFFIX="frompretrain_raw_ep${PATCHTST_PRETRAIN_EPOCHS}" \
                run_finetune   patchtst "$MODE" --context_length "$WINDOW_LEN"
        done

        echo ">>> fold_${k}/${FEAT} done"
    done

    echo ">>> FOLD ${k} complete"
done

echo ""
echo ">>> All 10-class kfold experiments done"
echo ">>> Results under: ${KFOLD_RUN_DIR}"
